properties.query:
let rttThreshold = toscalar(
    _GetWatchlist('UAV_Threshold_List')
    | where ThresholdKey == 'MaxRttMs_SATCOM'
    | project toreal(Value));
let jamThreshold = toscalar(
    _GetWatchlist('UAV_Threshold_List')
    | where ThresholdKey == 'MaxJamIndicator'
    | project toreal(Value));
let knownSrc = dynamic(["10.60.0.10"]);
let alertWindow = 10m;
let IntegrityAlert =
    UAVSatcomLink_CL
    | where TimeGenerated > ago(alertWindow)
    | where IntegrityStatus != 'ok'
    | summarize Count=count(), FirstSeen=min(TimeGenerated) by UAVId, LinkId, SessionId, IntegrityStatus
    | extend TriggerReason = strcat("SATCOM_무결성_위반_", IntegrityStatus), Severity = "High";
let RttAlert =
    UAVSatcomLink_CL
    | where TimeGenerated > ago(alertWindow)
    | where toreal(RttMs) > rttThreshold
    | summarize MaxRtt=max(toreal(RttMs)), Count=count(), FirstSeen=min(TimeGenerated) by UAVId, LinkId, SessionId
    | extend TriggerReason = strcat("SATCOM_RTT_급증_", tostring(toint(MaxRtt)), "ms"), Severity = "Medium";
let JamAlert =
    UAVSatcomLink_CL
    | where TimeGenerated > ago(alertWindow)
    | where toreal(JamIndicator) > jamThreshold
    | summarize MaxJam=max(toreal(JamIndicator)), Count=count(), FirstSeen=min(TimeGenerated) by UAVId, LinkId, SessionId
    | extend TriggerReason = strcat("SATCOM_재밍_JamIndicator_", tostring(MaxJam)), Severity = "High";
let SrcAlert =
    UAVSatcomLink_CL
    | where TimeGenerated > ago(alertWindow)
    | where SrcAddr !in (knownSrc)
    | summarize Count=count(), FirstSeen=min(TimeGenerated) by UAVId, LinkId, SessionId, SrcAddr
    | extend TriggerReason = strcat("SATCOM_비인가_SrcAddr_", SrcAddr), Severity = "High";
union IntegrityAlert, RttAlert, JamAlert, SrcAlert
| extend IncidentType = "S3_SATCOM_MITM"
| project FirstSeen, UAVId, LinkId, SessionId, TriggerReason, Severity, IncidentType
| order by Severity desc, FirstSeen asc
